function validateRoot(root) {
  let checked = root;
  if (typeof checked === 'string') {
    const rootLength = path.parse(checked).root.length;
    while (checked.length > rootLength && checked.endsWith(path.sep)) checked = checked.slice(0, -1);
  }
  const stat = fs.lstatSync(checked);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) throw Error('manifest must be an object');
  if (manifest.version !== 1) throw Error('unsupported manifest version');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
  const seen = new Set();
  const files = manifest.files.map(entry => {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('manifest entry must be an object');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) throw Error('invalid sha256');
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('invalid size');
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid mode');
    return {path:entry.path,sha256:entry.sha256,size:entry.size,mode:entry.mode};
  });
  return files.sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
}

export function verifyManifest(root, manifest) {
  const files = validateManifest(manifest);
  validateRoot(root);
  const report = {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]};
  for (const expected of files) {
    const current = inspect(root, expected.path);
    if (current.kind === 'missing') report.missing.push(expected.path);
    else if (current.kind === 'unsafe') report.unsafe.push(expected.path);
    else {
      const reasons = [];
      if (current.sha256 !== expected.sha256 || current.size !== expected.size) reasons.push('content');
      if (current.mode !== expected.mode) reasons.push('mode');
      if (reasons.length) report.changed.push({path:expected.path,reasons});
      else report.unchanged.push(expected.path);
    }
  }
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(args) {
  if (args[0] === 'create' && args.length >= 2) return {value:createManifest(args[1], args.slice(2)), code:0};
  if (args[0] === 'verify' && args.length === 3) {
    const manifest = JSON.parse(fs.readFileSync(args[2], 'utf8'));
    const value = verifyManifest(args[1], manifest);
    return {value, code:value.ok ? 0 : 1};
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | snapshot.js verify ROOT MANIFEST_FILE');
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname)) {
  try {
    const result = runCli(process.argv.slice(2));
    process.stdout.write(`${JSON.stringify(result.value)}\n`);
    process.exitCode = result.code;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

