import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath, pathToFileURL} from 'node:url';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-cli-'));
  fs.writeFileSync(path.join(dir, 'a.txt'), Buffer.from([0, 10, 255]));
  fs.chmodSync(path.join(dir, 'a.txt'), 0o640);
  t.after(() => fs.rmSync(dir, {recursive:true,force:true}));
  return dir;
}
function run(args, options={}) {
  return spawnSync(process.execPath, [script, ...args], {encoding:'utf8', ...options});
}
function expectedManifest() {
  const bytes = Buffer.from([0, 10, 255]);
  return {version:1,files:[{path:'a.txt',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:3,mode:0o640}]};
}

test('create CLI writes exactly one JSON value and exits zero', t => {
  const dir = fixture(t);
  const result = run(['create', dir, 'a.txt']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, `${JSON.stringify(expectedManifest())}\n`);
  assert.equal(result.stderr, '');
});

test('verify CLI has exact success and drift output and exit codes', t => {
  const dir = fixture(t);
  const manifestFile = path.join(dir, 'manifest.json');
  fs.writeFileSync(manifestFile, JSON.stringify(expectedManifest()));
  let result = run(['verify', dir, manifestFile]);
  const okay = {ok:true,unchanged:['a.txt'],changed:[],missing:[],unsafe:[]};
  assert.equal(result.status, 0);
  assert.equal(result.stdout, `${JSON.stringify(okay)}\n`);
  assert.equal(result.stderr, '');
  fs.writeFileSync(path.join(dir, 'a.txt'), 'changed');
  result = run(['verify', dir, manifestFile]);
  const drift = {ok:false,unchanged:[],changed:[{path:'a.txt',reasons:['content']}],missing:[],unsafe:[]};
  assert.equal(result.status, 1);
  assert.equal(result.stdout, `${JSON.stringify(drift)}\n`);
  assert.equal(result.stderr, '');
});

test('all CLI errors exit two with stderr and no stdout', t => {
  const dir = fixture(t);
  const malformed = path.join(dir, 'bad.json');
  const invalid = path.join(dir, 'invalid.json');
  fs.writeFileSync(malformed, '{');
  fs.writeFileSync(invalid, JSON.stringify({version:2,files:[]}));
  const cases = [
    [], ['unknown'], ['create'], ['verify',dir], ['verify',dir,invalid,'extra'],
    ['create',path.join(dir,'missing')], ['create',dir,'../bad'],
    ['verify',dir,malformed], ['verify',dir,invalid], ['verify',dir,path.join(dir,'absent.json')],
  ];
  for (const args of cases) {
    const result = run(args);
    assert.equal(result.status, 2, args.join(' '));
    assert.equal(result.stdout, '', args.join(' '));
    assert.notEqual(result.stderr, '', args.join(' '));
  }
});

test('importing the module does not execute the CLI', () => {
  const source = `import(${JSON.stringify(pathToFileURL(script).href)})`;
  const result = spawnSync(process.execPath, ['--input-type=module','-e',source], {encoding:'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

