import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {createManifest, verifyManifest} from '../snapshot.js';

function root(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(dir, {recursive:true, force:true}));
  return dir;
}
function put(dir, name, bytes='data', mode=0o640) {
  const file = path.join(dir, name);
  fs.mkdirSync(path.dirname(file), {recursive:true});
  fs.writeFileSync(file, bytes);
  fs.chmodSync(file, mode);
}
function digest(value) { return crypto.createHash('sha256').update(value).digest('hex'); }
const validEntry = () => ({path:'a', sha256:digest('a'), size:1, mode:0o600});

test('manifest validation covers shape, fields, bounds, paths, and duplicates', t => {
  const dir = root(t);
  const badManifests = [
    null, [], 1, {}, {version:2,files:[]}, {version:1}, {version:1,files:{}},
    {version:1,files:[null]}, {version:1,files:[[]]},
    ...[undefined, '', 'A'.repeat(64), '0'.repeat(63), '0'.repeat(65)].map(sha256 => ({version:1,files:[{...validEntry(),sha256}]})),
    ...[-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '1'].map(size => ({version:1,files:[{...validEntry(),size}]})),
    ...[-1, 512, 1.5, '384'].map(mode => ({version:1,files:[{...validEntry(),mode}]})),
    ...[undefined, '', '/a', 'a\\b', 'a\0b', 'a//b', './a', 'a/.', '../a', 'a/..'].map(p => ({version:1,files:[{...validEntry(),path:p}]})),
    {version:1,files:[validEntry(), validEntry()]},
  ];
  for (const manifest of badManifests) assert.throws(() => verifyManifest(dir, manifest));
  assert.throws(() => verifyManifest(path.join(dir, 'absent'), {version:1,files:[validEntry(), {...validEntry(),path:'b',sha256:'bad'}]}), /sha256/);
});

test('frozen unsorted manifests are not mutated and output uses JS string order', t => {
  const dir = root(t);
  const names = ['😀', 'é', 'z', '\n'];
  for (const name of names) put(dir, name, name);
  const made = createManifest(dir, names);
  assert.deepEqual(made.files.map(x => x.path), ['\n','z','é','😀']);
  const files = made.files.slice().reverse().map(entry => Object.freeze({...entry, ignored:true}));
  const manifest = Object.freeze({version:1, files:Object.freeze(files), ignored:'yes'});
  const before = JSON.stringify(manifest);
  assert.deepEqual(verifyManifest(dir, manifest), {
    ok:true, unchanged:['\n','z','é','😀'], changed:[], missing:[], unsafe:[],
  });
  assert.equal(JSON.stringify(manifest), before);
  assert.deepEqual(files.map(x => x.path), ['😀','é','z','\n']);
});

test('empty selections work and valid path characters are accepted', t => {
  const dir = root(t);
  const emptyPaths = Object.freeze([]);
  assert.deepEqual(createManifest(dir, emptyPaths), {version:1,files:[]});
  assert.deepEqual(emptyPaths, []);
  assert.deepEqual(verifyManifest(dir, Object.freeze({version:1,files:Object.freeze([])})), {
    ok:true,unchanged:[],changed:[],missing:[],unsafe:[],
  });
  for (const name of ['space name', 'tab\tname', 'line\nname', '雪']) put(dir, name, name);
  assert.equal(createManifest(dir, ['space name','tab\tname','line\nname','雪']).files.length, 4);
});

test('reports content, size, mode, and combined drift with ordered reasons', t => {
  const dir = root(t);
  for (const name of ['same','bytes','size','mode','both','ignored']) put(dir, name, 'abc', 0o640);
  const manifest = createManifest(dir, ['same','bytes','size','mode','both']);
  fs.writeFileSync(path.join(dir, 'bytes'), 'xyz');
  const sizeEntry = manifest.files.find(x => x.path === 'size');
  sizeEntry.size++;
  fs.chmodSync(path.join(dir, 'mode'), 0o600);
  fs.writeFileSync(path.join(dir, 'both'), 'longer');
  fs.chmodSync(path.join(dir, 'both'), 0o600);
  fs.unlinkSync(path.join(dir, 'ignored'));
  assert.deepEqual(verifyManifest(dir, manifest), {
    ok:false,
    unchanged:['same'],
    changed:[
      {path:'both',reasons:['content','mode']},
      {path:'bytes',reasons:['content']},
      {path:'mode',reasons:['mode']},
      {path:'size',reasons:['content']},
    ],
    missing:[],unsafe:[],
  });
});

test('classifies first failing path component without following symlinks', t => {
  const dir = root(t);
  put(dir, 'target/file', 'x');
  put(dir, 'middle', 'x');
  fs.mkdirSync(path.join(dir, 'folder'));
  fs.symlinkSync(path.join(dir, 'target'), path.join(dir, 'link-in'));
  fs.symlinkSync(path.join(dir, 'no-target'), path.join(dir, 'dangling'));
  const paths = ['gone/child','absent','link-in/file','dangling/child','middle/child','folder'];
  const files = paths.map(p => ({path:p,sha256:digest('x'),size:1,mode:0o640})).reverse();
  assert.deepEqual(verifyManifest(dir, {version:1,files}), {
    ok:false,unchanged:[],changed:[],
    missing:['absent','gone/child'],
    unsafe:['dangling/child','folder','link-in/file','middle/child'],
  });
});

test('root must exist and be a non-symlink directory even with trailing separators', t => {
  const dir = root(t);
  put(dir, 'file');
  const link = `${dir}-link`;
  fs.symlinkSync(dir, link);
  t.after(() => fs.rmSync(link, {force:true}));
  const empty = {version:1,files:[]};
  assert.throws(() => verifyManifest(path.join(dir, 'file'), empty));
  assert.throws(() => verifyManifest(path.join(dir, 'missing'), empty));
  assert.throws(() => verifyManifest(`${link}${path.sep}`, empty), /non-symlink/);
  assert.throws(() => createManifest(`${link}${path.sep}`, []), /non-symlink/);
});

